export function Logo({ className, title = "SB Locksmith and Automotive" }: { className?: string; title?: string }) {
  const id = useId();
  const grad = `sb-logo-grad-${id.replace(/:/g, "")}`;
  return (
    <svg viewBox="0 0 3156 1542" role="img" aria-label={title} className={className}>
      <defs>
        <linearGradient id={grad} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" style={{ stopColor: "var(--logo-1, #F2D37A)" }} />
          <stop offset="0.5" style={{ stopColor: "var(--logo-2, #D4AF37)" }} />
          <stop offset="1" style={{ stopColor: "var(--logo-3, #B8892A)" }} />
        </linearGradient>
      </defs>
      {PATHS.map((p) => (
        <path key={p.t} d={p.d} transform={p.t} fill={`url(#${grad})`} />
      ))}
    </svg>
  );
}
